        items = [
            {"name": "zinc", "quantity": 11},
            {"name": "bolt", "quantity": 4},
            {"name": "nut", "quantity": 12},
        ]
        self.assertEqual(low_stock(items), ["bolt", "zinc"])


if __name__ == "__main__":
    unittest.main()
"}

